from pathlib import Path
p=Path('components/WorkflowWorkspaceV2.tsx')
s=p.read_text()
old='''<div className="mt-2 flex flex-wrap items-center justify-between gap-2 border-t border-slate-200/70 pt-2"><div className="flex min-w-0 flex-wrap gap-1.5 text-[10px] font-bold text-slate-600">{shift.offices?.languages?.length ? <span className="rounded-full bg-slate-50 px-2 py-1">◉ {shift.offices.languages.slice(0, 2).join(", ")}</span> : null}{shift.offices?.operatories ? <span className="rounded-full bg-slate-50 px-2 py-1">{shift.offices.operatories} operatories</span> : null}{shift.offices?.parking_info ? <span className="rounded-full bg-slate-50 px-2 py-1">P Parking</span> : null}{shift.notes && <span className="rounded-full bg-slate-50 px-2 py-1">Shift notes</span>}</div><button type="button" onClick={() => setExpanded((value) => !value)} className="secondary-btn shrink-0 px-3 py-1.5 text-xs">{expanded ? "Hide details" : "Details"}</button></div>'''
new='''<div className="mt-2 border-t border-slate-200/70 pt-2"><div className="flex min-w-0 flex-wrap items-center gap-1.5 text-[10px] font-bold text-slate-600">{shift.offices?.languages?.length ? <span className="rounded-full bg-slate-50 px-2 py-1">◉ {shift.offices.languages.slice(0, 2).join(", ")}</span> : null}{shift.offices?.operatories ? <span className="rounded-full bg-slate-50 px-2 py-1">{shift.offices.operatories} operatories</span> : null}{shift.offices?.parking_info ? <span className="rounded-full bg-slate-50 px-2 py-1">P Parking</span> : null}{shift.notes && <span className="rounded-full bg-slate-50 px-2 py-1">Shift notes</span>}<button type="button" onClick={() => setExpanded((value) => !value)} className="ml-0.5 inline-flex items-center rounded-full border border-slate-300 bg-white px-2.5 py-1 text-[10px] font-black text-[#002757] hover:bg-slate-50">{expanded ? "Hide Details" : "Details"}</button></div></div>'''
if old not in s: raise SystemExit('details row anchor not found')
s=s.replace(old,new,1)
p.write_text(s)
print('Details button now sits inline with office information chips.')